export function modulorPath(project){
 return MODULOR_CONTOURS.map(contour=>{
  const p=contour.map(([x,y])=>project(x,y));
  if(p.some(v=>!v||!v.every(Number.isFinite)))return '';
  return p.map((v,i)=>(i?'L':'M')+v.map(n=>Number(n.toFixed(4))).join(' ')).join('')+'Z';
 }).join('');
}
